{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_04\",\"table_name\":\"ledger\",\"query\":\"WITH ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER (PARTITION BY kind,event_key ORDER BY revision DESC) AS rn FROM ledger WHERE datetime(recorded_at)<=datetime('2026-10-24T12:00:00') AND date(business_date)<=date('2026-10-23')), active AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1 AND status<>'void') SELECT i.event_key,i.business_date,i.amount_minor,i.currency,i.discount_until,i.terms_code,COALESCE((SELECT SUM(p.amount_minor) FROM active p WHERE p.kind='payment' AND p.invoice_id=i.event_key),0) AS payments,COALESCE((SELECT SUM(c.amount_minor) FROM active c WHERE c.kind='credit' AND c.invoice_id=i.event_key),0) AS credits,COALESCE((SELECT SUM(h.amount_minor) FROM active h WHERE h.kind='hold' AND h.status='active' AND h.invoice_id=i.event_key),0) AS holds,(SELECT t.discount_bps FROM active t WHERE t.kind='terms' AND t.terms_code=i.terms_code AND date(t.business_date)<=date(i.business_date) ORDER BY date(t.business_date) DESC LIMIT 1) AS discount_bps,(SELECT f.fx_num FROM active f WHERE f.kind='fx' AND f.currency=i.currency AND date(f.business_date)<=date(i.business_date) ORDER BY date(f.business_date) DESC LIMIT 1) AS fx_num,(SELECT f.fx_den FROM active f WHERE f.kind='fx' AND f.currency=i.currency AND date(f.business_date)<=date(i.business_date) ORDER BY date(f.business_date) DESC LIMIT 1) AS fx_den FROM active i WHERE i.kind='invoice' AND i.vendor='BLUE' AND date(i.due_date)<=date('2026-10-30') ORDER BY i.event_key\"}}"}}
